  function menu(items,x,y){closeMenu();clearHover();lastFocus=document.activeElement;const el=document.createElement('div');el.className='shell-menu';el.setAttribute('role','menu');for(const it of items){if(it.separator){const hr=document.createElement('div');hr.className='menu-rule';hr.setAttribute('role','separator');el.append(hr);continue;}if(it.caption){const c=document.createElement('div');c.className='menu-caption';c.textContent=it.caption;el.append(c);continue;}const b=document.createElement('button');b.type='button';b.setAttribute('role',it.checked!==undefined?'menuitemcheckbox':'menuitem');if(it.checked!==undefined)b.setAttribute('aria-checked',String(it.checked));b.disabled=!!it.disabled;b.innerHTML=`<span class="menu-icon">${icon(it.checked?'check':it.icon||'blank',16)}</span><span class="menu-label">${esc(it.label)}</span>${it.shortcut?`<span class="menu-shortcut">${esc(it.shortcut)}</span>`:''}${it.children?icon('chevronRight',12):''}`;if(it.checked)b.classList.add('menu-checked');b.onclick=e=>{e.stopPropagation();if(it.children){const r=b.getBoundingClientRect();menu(it.children,r.right-4,r.top);}else{closeMenu();it.onClick?.();}};el.append(b);}$('#shell-popups').append(el);menuEl=el;positionPopup(el,x,y);const buttons=$$('button:not(:disabled)',el);el.onkeydown=e=>{const idx=buttons.indexOf(document.activeElement);if(['ArrowDown','ArrowUp','Home','End'].includes(e.key)){e.preventDefault();buttons[e.key==='Home'?0:e.key==='End'?buttons.length-1:(idx+(e.key==='ArrowDown'?1:buttons.length-1))%buttons.length]?.focus();}if(e.key==='Escape'){closeMenu();lastFocus?.focus();}};return el;}
  function flyout(id,classes,html){if(popup?.id===id){closePopups();return null;}closePopups();lastFocus=document.activeElement;const el=document.createElement('section');el.className='shell-flyout '+classes;el.id=id;el.innerHTML=html;$('#shell-popups').append(el);popup=el;return el;}
  function showStart(){const el=flyout('start-menu','start-menu',`<div class="start-inner"><div class="start-search">${icon('search',17)}<input aria-label="Wyszukaj aplikacje, ustawienia i dokumenty" placeholder="Wyszukaj aplikacje, ustawienia i dokumenty"></div><div id="start-content"></div></div><div class="start-footer"><button class="start-user"><span class="avatar">${icon('user',22)}</span>Gabinet weterynaryjny</button><button class="shell-icon-button" id="start-power" aria-label="Zasilanie">${icon('power',20)}</button></div>`);if(!el)return;renderStartPinned(el);$('.start-search input',el).addEventListener('input',e=>showSearch(e.target.value));$('.start-user',el).onclick=()=>Shell.openSettings('system');$('#start-power',el).onclick=e=>menu([{label:'Zablokuj',icon:'lock',onClick:()=>power('lock')},{label:'Uśpij',icon:'moon',onClick:()=>power('sleep')},{label:'Zamknij',icon:'power',onClick:()=>power('shutdown')},{label:'Uruchom ponownie',icon:'refresh',onClick:()=>power('restart')}],e.clientX-220,e.clientY-180);}
  const pinnedIds=['clinic','opisai','explorer','notepad','settings','help','history','terminal','recycleBin','contact','personalization','shortcuts'];
  function renderStartPinned(el){const content=$('#start-content',el);content.innerHTML=`<div class="start-section-head">Przypięte<button class="small-button" id="all-apps">Wszystkie ${icon('chevronRight',10)}</button></div><div class="start-pinned">${pinnedIds.filter(id=>apps.has(id)).map(id=>{const a=apps.get(id);return `<button class="start-app" data-open="${id}">${icon(a.icon,32)}<span>${esc(a.title)}</span></button>`;}).join('')}</div><div class="start-section-head">Polecane<button class="small-button" id="more-recommended">Więcej ${icon('chevronRight',10)}</button></div><div class="start-recommended"><button class="recommended-item" data-open="clinic">${icon('clinic',32)}<span class="recommended-copy">Fistaszek — wizyta<small>Ostatnio otwierane</small></span></button><button class="recommended-item" data-open="help">${icon('document',32)}<span class="recommended-copy">Pierwsze kroki z OpisAI<small>Dyktowanie i opisy wizyt</small></span></button><button class="recommended-item" data-open="history">${icon('history',30)}<span class="recommended-copy">Historia opracowań<small>Zapisane na tym urządzeniu</small></span></button><button class="recommended-item" data-open="notepad">${icon('notepad',32)}<span class="recommended-copy">Notatki<small>Dokument tekstowy</small></span></button></div>`;bindOpen(content);$('#all-apps',el).onclick=()=>renderAllApps(el);$('#more-recommended',el).onclick=()=>openApp('explorer');}
  function renderAllApps(el){const content=$('#start-content',el);content.innerHTML=`<div class="start-section-head">Wszystkie aplikacje<button class="small-button" id="back-pinned">${icon('chevronLeft',10)} Wstecz</button></div><div class="all-apps-list">${[...apps.values()].sort((a,b)=>a.title.localeCompare(b.title,'pl')).map(a=>`<button class="start-app" data-open="${a.id}">${icon(a.icon,28)}<span>${esc(a.title)}</span></button>`).join('')}</div>`;bindOpen(content);$('#back-pinned',el).onclick=()=>renderStartPinned(el);}
  function bindOpen(root){$$('[data-open]',root).forEach(b=>b.onclick=()=>openApp(b.dataset.open));}
  function showSearch(query=''){let el;if(popup?.id==='search-panel'){el=popup;}else el=flyout('search-panel','search-panel',`<div class="search-field">${icon('search',18)}<input placeholder="Wpisz tutaj, aby wyszukać" aria-label="Wyszukaj na pulpicie"></div><div class="search-categories"><button class="selected">Wszystko</button><button>Aplikacje</button><button>Dokumenty</button><button>Ustawienia</button></div><div class="search-results"></div>`);if(!el)return;const input=$('input',el);input.value=query;input.focus();const update=()=>{const q=input.value.toLocaleLowerCase('pl');const found=[...apps.values()].filter(a=>a.title.toLocaleLowerCase('pl').includes(q)||(a.keywords||'').includes(q)).slice(0,7);$('.search-results',el).innerHTML=`<div class="search-result-list"><h4>${q?'Najlepsze dopasowanie':'Najpopularniejsze aplikacje'}</h4>${found.length?found.map((a,i)=>`<button class="search-result ${i===0?'selected':''}" data-open="${a.id}">${icon(a.icon,28)}<span>${esc(a.title)}<small>Aplikacja</small></span></button>`).join(''):'<p class="setting-description">Nie znaleziono wyników. Spróbuj wpisać „OpisAI”, „Klinika” lub „Ustawienia”.</p>'}</div>${found.length?`<div class="search-detail">${icon(found[0].icon,64)}<h3>${esc(found[0].title)}</h3><p>Aplikacja</p><button class="win-button" data-open="${found[0].id}">${icon('arrowRight',16)} Otwórz</button></div>`:''}`;bindOpen(el);};input.oninput=update;input.onkeydown=e=>{if(e.key==='Enter')$('.search-result',el)?.click();};$$('.search-categories button',el).forEach(b=>b.onclick=()=>{$$('.search-categories button',el).forEach(x=>x.classList.toggle('selected',x===b));if(b.textContent==='Dokumenty')input.value='notatki';else if(b.textContent==='Ustawienia')input.value='ustawienia';else input.value='';update();});update();}
  function showQuick(){const tiles=[['wifi','Wi-Fi',prefs.wifi],['bluetooth','Bluetooth',prefs.bluetooth],['airplane','Tryb samolotowy',false],['battery','Oszczędzanie energii',false],['moon','Wyświetlanie nocne',false],['accessibility','Ułatwienia dostępu',false]];const el=flyout('quick-settings','quick-panel',`<div class="quick-grid">${tiles.map(([id,label,on])=>`<div class="quick-tile"><button data-quick="${id}" aria-label="${label}" aria-pressed="${on}">${icon(id,21)}</button><span>${label}</span></div>`).join('')}</div><div class="quick-sliders"><label class="quick-slider">${icon('sun',20)}<input type="range" min="35" max="100" value="${prefs.brightness}" aria-label="Jasność"></label><label class="quick-slider">${icon('volume',20)}<input type="range" min="0" max="100" value="${prefs.volume}" aria-label="Głośność"></label></div><div class="quick-footer"><span>${icon('battery',18)} 86%</span><button class="shell-icon-button" aria-label="Wszystkie ustawienia">${icon('settings',18)}</button></div>`);if(!el)return;$$('[data-quick]',el).forEach(b=>b.onclick=()=>{const on=b.getAttribute('aria-pressed')!=='true';b.setAttribute('aria-pressed',on);if(b.dataset.quick==='wifi')prefs.wifi=on;if(b.dataset.quick==='bluetooth')prefs.bluetooth=on;if(b.dataset.quick==='moon')$('#desktop').style.filter=on?'sepia(.15)':'';if(b.dataset.quick==='airplane'){prefs.wifi=!on;$('[data-quick=wifi]',el).setAttribute('aria-pressed',!on);}if(b.dataset.quick==='accessibility')Shell.openSettings('accessibility');savePrefs();});$('input[aria-label="Jasność"]',el).oninput=e=>{prefs.brightness=+e.target.value;$('#desktop').style.opacity=String(prefs.brightness/100);savePrefs();};$('input[aria-label="Głośność"]',el).oninput=e=>{prefs.volume=+e.target.value;savePrefs();};$('.quick-footer button',el).onclick=()=>Shell.openSettings('system');}
  function showCalendar(){const el=flyout('calendar-panel','calendar-panel',`<div class="notifications-header"><span>Powiadomienia</span><button class="shell-icon-button" id="quiet-mode" title="Nie przeszkadzać" aria-label="Nie przeszkadzać" aria-pressed="${prefs.quiet}">${icon(prefs.quiet?'moon':'notification',18)}</button></div><div class="notification-list"></div><div class="calendar-section"><div class="calendar-today"></div><div class="calendar-nav"><span></span><div><button class="shell-icon-button" id="month-prev" aria-label="Poprzedni miesiąc">${icon('chevronUp',12)}</button><button class="shell-icon-button" id="month-next" aria-label="Następny miesiąc">${icon('chevronDown',12)}</button></div></div><div class="calendar-grid"></div></div><div class="focus-footer"><div class="focus-duration"><button class="shell-icon-button" id="focus-less" aria-label="Skróć czas skupienia">−</button><span id="focus-duration"></span><button class="shell-icon-button" id="focus-more" aria-label="Wydłuż czas skupienia">+</button></div><button class="win-button" id="focus-start">${icon('play',14)} Skupienie</button></div>`);if(!el)return;$('.notification-list',el).innerHTML=notifications.length?notifications.slice(-3).reverse().map(n=>`<div class="notification-card"><div class="notification-card-header">${icon(n.icon||'opisai',16)} OpisAI <span style="margin-left:auto;color:var(--muted)">${esc(n.time)}</span></div><p><strong>${esc(n.title)}</strong></p><p>${esc(n.message)}</p></div>`).join(''):'<div class="notifications-empty">Nie masz nowych powiadomień</div>';const render=()=>{const now=new Date(),date=new Date(now.getFullYear(),now.getMonth()+calendarOffset,1),start=new Date(date);start.setDate(1-((date.getDay()+6)%7));$('.calendar-today',el).textContent=now.toLocaleDateString('pl-PL',{weekday:'long',day:'numeric',month:'long'});$('.calendar-nav>span',el).textContent=date.toLocaleDateString('pl-PL',{month:'long',year:'numeric'});$('.calendar-grid',el).innerHTML=['Pn','Wt','Śr','Cz','Pt','So','Nd'].map(d=>`<span class="weekday">${d}</span>`).join('')+Array.from({length:42},(_,i)=>{const d=new Date(start);d.setDate(start.getDate()+i);return `<button class="calendar-day ${d.getMonth()!==date.getMonth()?'outside':''} ${d.toDateString()===now.toDateString()?'today':''}" aria-label="${d.toLocaleDateString('pl-PL',{day:'numeric',month:'long',year:'numeric'})}">${d.getDate()}</button>`;}).join('');$$('.calendar-day',el).forEach(b=>b.onclick=()=>{$$('.calendar-day',el).forEach(d=>d.classList.remove('selected'));b.classList.add('selected');});$('#focus-duration',el).textContent=focusMinutes+' min';$('#focus-start',el).textContent=focusUntil?'Zakończ skupienie':'Skupienie';};$('#month-prev',el).onclick=()=>{calendarOffset--;render();};$('#month-next',el).onclick=()=>{calendarOffset++;render();};$('#quiet-mode',el).onclick=()=>{prefs.quiet=!prefs.quiet;savePrefs();$('#quiet-mode',el).setAttribute('aria-pressed',prefs.quiet);$('#quiet-mode',el).innerHTML=icon(prefs.quiet?'moon':'notification',18);};$('#focus-less',el).onclick=()=>{focusMinutes=Math.max(5,focusMinutes-5);render();};$('#focus-more',el).onclick=()=>{focusMinutes=Math.min(240,focusMinutes+5);render();};$('#focus-start',el).onclick=()=>{focusUntil=focusUntil?0:Date.now()+focusMinutes*60000;prefs.quiet=!!focusUntil;savePrefs();render();};render();}
  function notify(n){const now=new Date();notifications.push({...n,time:now.toLocaleTimeString('pl-PL',{hour:'2-digit',minute:'2-digit'})});if(notifications.length>30)notifications.shift();if(prefs.quiet)return;const el=document.createElement('div');el.className='windows-toast';el.innerHTML=`<div class="toast-top">${icon(n.icon||'opisai',18)}<span>${esc(n.app||'OpisAI')}</span><button aria-label="Odrzuć powiadomienie">${icon('close',12)}</button></div><h4>${esc(n.title||'OpisAI')}</h4><p>${esc(n.message||'')}</p>${n.actionLabel?`<button class="win-button">${esc(n.actionLabel)}</button>`:''}`;$('#notification-toasts').append(el);$('.toast-top button',el).onclick=()=>el.remove();if(n.actionLabel)$('.win-button',el).onclick=()=>{el.remove();n.onAction?.();};let timeout=setTimeout(()=>el.remove(),n.duration||9000);el.onpointerenter=()=>clearTimeout(timeout);el.onpointerleave=()=>{timeout=setTimeout(()=>el.remove(),4000);};$('#shell-status').textContent=[n.title,n.message].join('. ');}
  function toast(message){const el=document.createElement('div');el.className='windows-toast status-toast';el.textContent=message;$('#notification-toasts').append(el);setTimeout(()=>el.remove(),3600);$('#shell-status').textContent=message;}
  function confirm(o){const win=createWindow({id:'confirmation-'+Date.now(),title:o.title||'OpisAI',icon:o.icon||'opisai',width:470,height:220,minWidth:300,minHeight:180,resizable:false,maximizable:false,taskbar:false,content:`<div class="message-body">${icon(o.icon||'info',32)}<div>${o.heading?`<h3>${esc(o.heading)}</h3>`:''}<p>${esc(o.message)}</p></div></div><div class="dialog-footer"><button class="win-button primary" data-confirm>${esc(o.confirmLabel||'OK')}</button>${o.onConfirm?`<button class="win-button" data-cancel>${esc(o.cancelLabel||'Anuluj')}</button>`:''}</div>`});$('[data-confirm]',win.content).onclick=()=>{win.close();o.onConfirm?.();};$('[data-cancel]',win.content)?.addEventListener('click',()=>{win.close();o.onCancel?.();});return win;}
  function showDesktop(){
    closePopups();const desktop=desktopById();
    if(!desktop.peek){
      const previousActive=active?.id;desktop.peekWindows=[...windows.values()].filter(win=>win.visible);
      desktop.peekWindows.forEach(win=>win.minimize(true));
      desktop.peek=desktop.peekWindows.length>0;desktop.lastActiveId=previousActive||desktop.lastActiveId;
    }else{
      const restore=desktop.peekWindows.slice();desktop.peekWindows=[];desktop.peek=false;
      for(const win of restore)if(!win.closed&&win.desktopId===desktop.id){win.el.hidden=false;win.el.classList.remove('minimizing');applyDesktopVisibility(win);}
      focusTopWindow(desktop.lastActiveId);
    }
  }
  function desktopPreview(desktop){
    const preview=document.createElement('span');preview.className='virtual-desktop-image';preview.setAttribute('aria-hidden','true');
    const scene=document.createElement('span');scene.className='virtual-desktop-scene';scene.inert=true;
    const area=workArea();Object.assign(scene.style,{width:area.width+'px',height:area.height+'px',transform:`scale(${150/Math.max(area.width,1)})`});
    for(const win of [...windows.values()].filter(win=>win.desktopId===desktop.id&&!win.el.hidden&&!win.el.classList.contains('minimizing')).sort((a,b)=>+a.el.style.zIndex-+b.el.style.zIndex)){
      const copy=win.el.cloneNode(true);copy.removeAttribute('id');copy.removeAttribute('tabindex');copy.inert=true;copy.hidden=false;copy.style.display='';copy.style.zIndex='auto';copy.style.boxShadow='0 2px 10px #0004';$$('[id]',copy).forEach(node=>node.removeAttribute('id'));$$('canvas',copy).forEach(node=>node.remove());scene.append(copy);
    }
    preview.append(scene);return preview;
  }
  function showTaskView(){
    if(popup?.id==='task-view'){closePopups();return;}
    closePopups();lastFocus=document.activeElement;
    const el=document.createElement('section');el.className='task-view';el.id='task-view';el.setAttribute('aria-label','Widok zadań — '+desktopById().name);
    const list=document.createElement('div');list.className='task-view-windows';
    const currentWindows=[...windows.values()].filter(win=>win.desktopId===currentDesktopId);
    for(const win of currentWindows){
      const card=document.createElement('button');card.type='button';card.className='task-view-card';card.setAttribute('aria-label','Przełącz do: '+win.options.title);
      card.innerHTML=`<div class="task-view-title">${icon(win.options.icon,20)}${esc(win.options.title)}</div>`;
      const image=thumbnail(win),copy=$('.desktop-window',image);copy.style.transform=`scale(${328/(win.el.offsetWidth||parseFloat(win.el.style.width)||800)})`;copy.style.display='';copy.inert=true;image.setAttribute('aria-hidden','true');card.append(image);
      card.onclick=()=>{closePopups();win.show();};list.append(card);
    }
    if(!currentWindows.length){const empty=document.createElement('p');empty.className='task-view-empty';empty.textContent='Brak otwartych okien na tym pulpicie';list.append(empty);}
    el.append(list);
    const bar=document.createElement('div');bar.className='virtual-desktop-bar';bar.setAttribute('aria-label','Pulpity');
    for(const desktop of virtualDesktops){
      const tile=document.createElement('div');tile.className='virtual-desktop-tile';
      const select=document.createElement('button');select.type='button';select.className='virtual-desktop'+(desktop.id===currentDesktopId?' current':'');select.setAttribute('aria-pressed',String(desktop.id===currentDesktopId));select.setAttribute('aria-label','Przełącz na '+desktop.name);
      select.append(desktopPreview(desktop));const label=document.createElement('span');label.className='virtual-desktop-name';label.textContent=desktop.name;select.append(label);select.onclick=()=>{switchDesktop(desktop.id);focusTopWindow(desktop.lastActiveId);};tile.append(select);
      if(virtualDesktops.length>1){const close=document.createElement('button');close.type='button';close.className='virtual-desktop-close';close.title='Zamknij '+desktop.name;close.setAttribute('aria-label','Zamknij '+desktop.name+' i przenieś jego okna');close.innerHTML=icon('close',10);close.onclick=()=>{removeDesktop(desktop.id);showTaskView();};tile.append(close);}
      bar.append(tile);
    }
    const add=document.createElement('button');add.type='button';add.className='virtual-desktop virtual-desktop-new';add.innerHTML='<span class="virtual-desktop-plus" aria-hidden="true">+</span><span>Nowy pulpit</span>';add.onclick=createDesktop;bar.append(add);
    el.append(bar);$('#shell-popups').append(el);popup=el;
    ($('.task-view-card',el)||$('.virtual-desktop.current',el))?.focus();
  }
  function showWidgets(){const el=flyout('widgets-panel','widgets-panel',`<h2 class="widgets-heading">Dzień dobry</h2><div class="widget-card"><h3>${icon('calendar',20)} Twój gabinet</h3><p id="widget-date"></p><button class="win-button" data-open="clinic">${icon('clinic',20)} Wróć do wizyty Fistaszka</button></div><div class="widget-card"><h3>OpisAI</h3><p>Opracuj notatkę z wizyty albo rozpocznij przykładowe dyktowanie. Wynik sprawdzisz przed wpisaniem do pól.</p><div class="widget-actions"><button class="win-button primary" id="widget-describe">Opisz wizytę</button><button class="win-button" id="widget-dictate">${icon('mic',16)} Dyktuj</button></div></div><div class="widget-card"><h3>Pierwsze kroki</h3><p>Kliknięcie bąbelka otwiera przygotowanie opisu. Przytrzymanie rozpoczyna dyktowanie. Wszystkie opcje znajdziesz pod prawym przyciskiem myszy.</p><button class="win-button" data-open="help">Otwórz przewodnik</button></div>`);if(!el)return;$('#widget-date',el).textContent=new Date().toLocaleDateString('pl-PL',{weekday:'long',day:'numeric',month:'long',year:'numeric'});bindOpen(el);$('#widget-describe',el).onclick=()=>{closePopups();window.OpisAI?.prepare();};$('#widget-dictate',el).onclick=()=>{closePopups();window.OpisAI?.dictate();};}
  function power(mode){closePopups();const el=document.createElement('div');el.className='screen-curtain'+(mode==='lock'?' lock-screen':'');if(mode==='lock'){el.innerHTML=`<div class="lock-clock">${new Date().toLocaleTimeString('pl-PL',{hour:'2-digit',minute:'2-digit'})}</div><div class="lock-date">${new Date().toLocaleDateString('pl-PL',{weekday:'long',day:'numeric',month:'long'})}</div><button class="win-button">Wróć do gabinetu</button>`;}else el.innerHTML=`${icon('windows',64)}<p>${mode==='restart'?'Ponowne uruchamianie pulpitu…':mode==='sleep'?'Pulpit jest uśpiony':'Pulpit został zamknięty'}</p><button class="win-button">${mode==='sleep'?'Wznów':'Uruchom pulpit'}</button>`;document.body.append(el);$('button',el).onclick=()=>el.remove();if(mode==='restart')setTimeout(()=>{el.remove();window.Clinic?.open();window.OpisAI?.showBubble();},1300);el.onkeydown=e=>{if(e.key==='Enter'||e.key==='Escape')el.remove();};$('button',el).focus();}
  function desktopMenu(e){if(e.target!==$('#desktop')&&e.target!==$('#desktop-icons')&&e.target!==$('#windows'))return;e.preventDefault();menu([{label:'Widok',icon:'view',children:[{label:'Duże ikony',onClick:()=>$('#desktop-icons').style.zoom='1.2'},{label:'Średnie ikony',checked:true,onClick:()=>$('#desktop-icons').style.zoom='1'},{label:'Małe ikony',onClick:()=>$('#desktop-icons').style.zoom='.85'},{separator:true},{label:'Pokaż ikony pulpitu',checked:!$('#desktop-icons').hidden,onClick:()=>$('#desktop-icons').hidden=!$('#desktop-icons').hidden}]},{label:'Sortuj według',icon:'sort',children:[{label:'Nazwa',onClick:()=>{const root=$('#desktop-icons');$$('.desktop-icon',root).sort((a,b)=>a.textContent.localeCompare(b.textContent,'pl')).forEach(x=>root.append(x));}},{label:'Typ elementu',onClick:()=>renderDesktopIcons()}]},{label:'Odśwież',icon:'refresh',onClick:()=>{const d=$('#desktop-icons');d.style.opacity='0';requestAnimationFrame(()=>requestAnimationFrame(()=>d.style.opacity='1'));}},{separator:true},{label:'Nowy',icon:'plus',children:[{label:'Dokument tekstowy',icon:'notepad',onClick:()=>Shell.openNotepad?.('Nowy dokument.txt','')}]},{separator:true},{label:'Ustawienia ekranu',icon:'computer',onClick:()=>Shell.openSettings('system')},{label:'Personalizuj',icon:'settings',onClick:()=>Shell.openSettings('personalization')},{separator:true},{label:'Pokaż więcej opcji',shortcut:'Shift+F10',onClick:()=>Shell.openSettings('shortcuts')}],e.clientX,e.clientY);}
  function renderDesktopIcons(){const entries=[['recycleBin','Kosz'],['clinic','Klinika XP'],['opisai','OpisAI'],['explorer','Dokumenty'],['help','OpisAI — pomoc']];$('#desktop-icons').innerHTML=entries.map(([id,label])=>`<button class="desktop-icon" data-app="${id}" title="${esc(label)}" aria-label="${esc(label)}">${icon(apps.get(id)?.icon||id,40)}<span>${esc(label)}</span></button>`).join('');$$('.desktop-icon').forEach(b=>{b.onclick=e=>{if(!e.ctrlKey)$$('.desktop-icon').forEach(x=>x.classList.remove('selected'));b.classList.add('selected');};b.ondblclick=()=>openApp(b.dataset.app);b.onkeydown=e=>{if(e.key==='Enter')openApp(b.dataset.app);};b.oncontextmenu=e=>{e.preventDefault();b.click();menu([{label:'Otwórz',icon:'arrowRight',onClick:()=>openApp(b.dataset.app)},{separator:true},{label:'Właściwości',shortcut:'Alt+Enter',onClick:()=>confirm({title:'Właściwości: '+b.textContent,icon:apps.get(b.dataset.app)?.icon||'document',message:b.dataset.app==='opisai'?'OpisAI 0.12.0rc32\nAsystent dokumentacji weterynaryjnej\nInteraktywna demonstracja przeglądarkowa.':b.textContent+'\nElement pulpitu demonstracji OpisAI.'})}],e.clientX,e.clientY);};});}
  function init(){
    applyPrefs();$('.taskbar-left').innerHTML=`<button class="taskbar-button taskbar-widget" aria-label="Widżety">${icon('widgets',27)}<span class="widget-copy">Gabinet<small>Twój pulpit</small></span></button>`;$('.taskbar-widget').onclick=showWidgets;
    $('.taskbar-tray').innerHTML=`<button class="tray-button tray-hidden" aria-label="Pokaż ukryte ikony">${icon('chevronUp',12)}</button><button class="tray-button tray-opisai" aria-label="Menu OpisAI">${icon('opisai',17)}</button><button class="tray-button tray-language" aria-label="Język klawiatury"><span>POL</span><span>PLP</span></button><button class="tray-button tray-controls" aria-label="Szybkie ustawienia">${icon('wifi',17)}${icon('volume',17)}${icon('battery',19)}</button><button class="tray-button clock-button" aria-label="Data, godzina i powiadomienia"><span class="clock-time"></span><span class="clock-date"></span></button><button class="show-desktop" aria-label="Pokaż pulpit" title="Pokaż pulpit"></button>`;
    $('.tray-controls').onclick=showQuick;$('.clock-button').onclick=showCalendar;$('.show-desktop').onclick=showDesktop;
    $('.tray-hidden').onclick=()=>{const el=flyout('hidden-icons','hidden-icons',`<button data-tray-action="opisai" aria-label="OpisAI">${icon('opisai',24)}</button><button data-tray-action="shield" aria-label="Informacje o prywatności">${icon('shield',24)}</button>`);if(el){$('[data-tray-action=opisai]',el).onclick=()=>{closePopups();window.OpisAI?.showBubble();};$('[data-tray-action=shield]',el).onclick=()=>Shell.openSettings('privacy');}};
    $('.tray-opisai').onclick=e=>menu([{label:'Opisz wizytę',icon:'opisai',onClick:()=>window.OpisAI?.prepare()},{label:'Dyktuj',icon:'mic',onClick:()=>window.OpisAI?.dictate()},{separator:true},{label:'Ustawienia OpisAI',icon:'settings',onClick:()=>window.OpisAI?.settings()},{label:'Historia',icon:'history',onClick:()=>window.OpisAI?.history()},{label:'O aplikacji',icon:'info',onClick:()=>window.OpisAI?.about()}],e.clientX-190,innerHeight-260);
    $('.tray-language').onclick=()=>{const el=flyout('language-panel','language-panel','<h4>Układ klawiatury</h4><button class="language-choice active"><span class="language-code">POL</span><span>Polski<small>Polski (programisty)</small></span></button><button class="language-choice"><span class="language-code">ENG</span><span>English (United States)<small>US</small></span></button>');if(el)$$('.language-choice',el).forEach(b=>b.onclick=()=>{$$('.language-choice',el).forEach(x=>x.classList.toggle('active',x===b));$('.tray-language').innerHTML=`<span>${$('.language-code',b).textContent}</span><span>${$('.language-code',b).textContent==='POL'?'PLP':'US'}</span>`;});};
    function clock(){const now=new Date();$('.clock-time').textContent=now.toLocaleTimeString('pl-PL',{hour:'2-digit',minute:'2-digit'});$('.clock-date').textContent=now.toLocaleDateString('pl-PL',{day:'2-digit',month:'2-digit',year:'numeric'});$('.clock-button').title=now.toLocaleDateString('pl-PL',{weekday:'long',day:'numeric',month:'long',year:'numeric'});if(focusUntil&&Date.now()>=focusUntil){focusUntil=0;prefs.quiet=false;notify({title:'Czas na przerwę',message:'Sesja skupienia została zakończona.'});}}clock();setInterval(clock,1000);renderTaskbar();renderDesktopIcons();setTimeout(renderDesktopIcons,0);
    $('#desktop').addEventListener('contextmenu',desktopMenu);
    $('#desktop').addEventListener('pointerdown',e=>{if(e.target!==$('#desktop')&&e.target!==$('#windows'))return;closePopups();$$('.desktop-icon').forEach(b=>b.classList.remove('selected'));if(e.button!==0)return;const sx=e.clientX,sy=e.clientY,box=$('#selection-box');const move=ev=>{box.hidden=false;const x=Math.min(sx,ev.clientX),y=Math.min(sy,ev.clientY),w=Math.abs(sx-ev.clientX),h=Math.abs(sy-ev.clientY);Object.assign(box.style,{left:x+'px',top:y+'px',width:w+'px',height:h+'px'});$$('.desktop-icon').forEach(b=>{const r=b.getBoundingClientRect();b.classList.toggle('selected',r.right>x&&r.left<x+w&&r.bottom>y&&r.top<y+h);});};const end=()=>{box.hidden=true;document.removeEventListener('pointermove',move);document.removeEventListener('pointerup',end);};document.addEventListener('pointermove',move);document.addEventListener('pointerup',end);});
    $('#taskbar').oncontextmenu=e=>{e.preventDefault();menu([{label:'Ustawienia paska zadań',icon:'settings',onClick:()=>Shell.openSettings('personalization')},{label:'Pokaż pulpit',icon:'computer',onClick:showDesktop}],e.clientX,e.clientY-85);};
    document.addEventListener('pointerdown',e=>{if(!e.target.closest('#shell-popups,#taskbar'))closePopups();if(menuEl&&!menuEl.contains(e.target)&&!e.target.closest('.titlebar'))closeMenu();},true);
    document.addEventListener('keydown',e=>{const editing=e.target.matches('input,textarea')||e.target.isContentEditable;if(e.key==='Escape'){if(menuEl||popup){closePopups();lastFocus?.focus();e.preventDefault();}else if(active&&!editing&&active.options.resizable===false)active.close();}if(e.ctrlKey&&e.key==='Escape'){e.preventDefault();showStart();}if(e.metaKey&&e.key.toLowerCase()==='s'){e.preventDefault();showSearch();}if(e.metaKey&&e.key.toLowerCase()==='d'){e.preventDefault();showDesktop();}if(e.metaKey&&e.key.toLowerCase()==='e'){e.preventDefault();openApp('explorer');}if(e.metaKey&&e.key.toLowerCase()==='i'){e.preventDefault();Shell.openSettings('system');}if(e.metaKey&&e.key==='ArrowLeft'&&active){e.preventDefault();snap(active,'left');}if(e.metaKey&&e.key==='ArrowRight'&&active){e.preventDefault();snap(active,'right');}if(e.metaKey&&e.key==='ArrowUp'&&active){e.preventDefault();snap(active,'full');}if(e.altKey&&e.key==='F4'&&active){e.preventDefault();active.close();}if(e.altKey&&e.code==='Space'&&active){e.preventDefault();const r=rect(active);systemMenu(active,r.x+8,r.y+32);menuEl?.querySelector('button:not(:disabled)')?.focus();}if(e.key==='F1'&&!editing){e.preventDefault();openApp('help');}if(e.key==='F5'&&!editing){e.preventDefault();renderDesktopIcons();}});
    window.addEventListener('resize',()=>{closePopups();for(const win of windows.values())if(win.maximized)setRect(win,{x:0,y:0,...workArea()});else setRect(win,fitRect(rect(win),win.options.minWidth,win.options.minHeight));});
  }
  window.Shell={createWindow,registerApp,openApp,menu,notify,toast,confirm,escape:esc,icon,apps,windows,prefs,applyPrefs,readStorage,closePopups,showStart,showSearch,showQuick,showCalendar,showDesktop,showTaskView,showWidgets,power,snap,renderTaskbar,workArea,createDesktop,switchDesktop,closeDesktop:removeDesktop,getDesktops:()=>virtualDesktops.map(desktop=>({id:desktop.id,name:desktop.name,current:desktop.id===currentDesktopId,windows:[...windows.values()].filter(win=>win.desktopId===desktop.id).length})),get currentDesktopId(){return currentDesktopId;},get activeWindow(){return active;},setTheme(theme){prefs.theme=theme;applyPrefs();},openSettings(){},openNotepad(){}};
